/**
 * @param {string} word
 * @return {number}
 */
var minimumPushes = function(word) {
    const freq = Array(26).fill(0);

    for (let i = 0; i < word.length; i++) {
        freq[word.charCodeAt(i) - 97]++;
    }

    freq.sort((a, b) => b - a);

    let sum = 0;

    for (let i = 0; i < 26; i++) {
        sum += freq[i] * (Math.floor(i / 8) + 1);
    }

    return sum;
};

